 const beforeJSON=`SELECT @before=(SELECT CONVERT(nvarchar(33),SYSUTCDATETIME(),126) capturedAtUtc,JSON_QUERY((SELECT JSON_QUERY((SELECT c.* FROM dbo.customers c WHERE c.id=TRY_CONVERT(bigint,JSON_VALUE(@proof,'$.customerId')) FOR JSON PATH,INCLUDE_NULL_VALUES)) customers,
JSON_QUERY((SELECT a.* FROM dbo.party_currency_accounts a WHERE a.id=TRY_CONVERT(bigint,JSON_VALUE(@proof,'$.accountId')) FOR JSON PATH,INCLUDE_NULL_VALUES)) party_currency_accounts,
JSON_QUERY((SELECT p.* FROM dbo.products p WHERE EXISTS(SELECT 1 FROM OPENJSON(@proof,'$.products') WITH(productId bigint '$.productId') i WHERE i.productId=p.id) ORDER BY p.id FOR JSON PATH,INCLUDE_NULL_VALUES)) products,
JSON_QUERY((SELECT v.* FROM dbo.sales_invoices v WHERE v.id=@invoice FOR JSON PATH,INCLUDE_NULL_VALUES)) sales_invoices,
JSON_QUERY((SELECT i.* FROM dbo.sales_invoice_items i WHERE i.sales_invoice_id=@invoice ORDER BY i.id FOR JSON PATH,INCLUDE_NULL_VALUES)) sales_invoice_items,
JSON_QUERY((SELECT s.* FROM dbo.stock_movements s WHERE s.source_type=N'sales_invoice' AND s.source_id=@invoice ORDER BY s.id FOR JSON PATH,INCLUDE_NULL_VALUES)) stock_movements,
JSON_QUERY((SELECT m.* FROM dbo.customer_movements m WHERE m.sales_invoice_id=@invoice ORDER BY m.id FOR JSON PATH,INCLUDE_NULL_VALUES)) customer_movements,
JSON_QUERY((SELECT a.* FROM dbo.audit_logs a WHERE a.entity_type=N'sales_invoice' AND a.entity_id=@invoice ORDER BY a.id FOR JSON PATH,INCLUDE_NULL_VALUES)) audit_logs,
JSON_QUERY((SELECT l.* FROM dbo.work_sales_links l WHERE l.invoice_id=@invoice ORDER BY l.invoice_id FOR JSON PATH,INCLUDE_NULL_VALUES)) work_sales_links,JSON_QUERY(N'[]') work_trade_requests FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) rows,
JSON_QUERY((SELECT ${['customers','party_currency_accounts','products','sales_invoices','sales_invoice_items','stock_movements','customer_movements','audit_logs','work_sales_links','work_trade_requests'].map(t=>`(SELECT COUNT_BIG(*) FROM dbo.${t}) ${t}`).join(',')} FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) totals,
JSON_QUERY((SELECT ${['finance_accounts','finance_account_movements','currency_rates'].map(t=>`JSON_QUERY((SELECT (SELECT COUNT_BIG(*) FROM dbo.${t}) count,CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT * FROM dbo.${t} ORDER BY id FOR JSON PATH,INCLUDE_NULL_VALUES)),2) hash FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) ${t}`).join(',')} FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) frozen,JSON_QUERY((SELECT ${outside} FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) outside FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);`;
 const beginDefinition=proc(O.begin,'@request_id uniqueidentifier,@actor_id bigint,@operation nvarchar(40),@payload_json nvarchar(max)',`${readyCall} ${lock('Exclusive')} ${bodyGuards}
DECLARE @bodyHash char(64)=CONVERT(varchar(64),HASHBYTES('SHA2_256',@payload_json),2),@oldActor bigint,@oldOp nvarchar(40),@oldHash char(64),@oldBody nvarchar(max),@response nvarchar(max);
SELECT @oldActor=actor_id,@oldOp=operation,@oldHash=payload_hash,@oldBody=payload_json,@response=response_json FROM dbo.work_trade_requests WITH(UPDLOCK,HOLDLOCK) WHERE request_id=@request_id;
IF @oldActor IS NOT NULL BEGIN IF @oldActor<>@actor_id OR @oldOp COLLATE Latin1_General_100_BIN2<>@operation OR @oldHash<>@bodyHash OR CONVERT(varbinary(max),@oldBody)<>CONVERT(varbinary(max),@payload_json) ${fail('REPLAY_CONFLICT')}
SELECT CAST(1 AS bit) replayed,@response response_json,@bodyHash bodyHash,CONVERT(varchar(20),@actor_id) actorId,@operation operation; RETURN; END;
IF EXISTS(SELECT 1 FROM ${O.intents} WHERE (session_id=@@SPID AND phase<>N'DONE') OR request_id=@request_id) ${fail('INTENT_EXISTS')}
DECLARE @selection nvarchar(max),@proof nvarchar(max),@context nvarchar(max),@invoice bigint=NULL,@creation nvarchar(max),@creationNative nvarchar(max),@creationRequest uniqueidentifier,@before nvarchar(max),@revision char(64);
IF @operation=N'sale_draft' SELECT @selection=(SELECT JSON_VALUE(@payload_json,'$.customerId') customerId,JSON_VALUE(@payload_json,'$.customerAccountId') customerAccountId,JSON_VALUE(@payload_json,'$.documentDate') documentDate,JSON_VALUE(@payload_json,'$.currency') currency,JSON_QUERY(@payload_json,'$.items') items FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
ELSE BEGIN
SET @invoice=TRY_CONVERT(bigint,JSON_VALUE(@payload_json,'$.id'));IF @invoice IS NULL ${fail('INVOICE_ID')}
SELECT @creation=j.payload_json,@creationRequest=j.request_id,@creationNative=snapshot.nativeCreationProofJSON FROM dbo.work_sales_links l WITH(UPDLOCK,HOLDLOCK) JOIN dbo.work_trade_requests j WITH(UPDLOCK,HOLDLOCK) ON j.request_id=l.request_id JOIN dbo.sales_invoices v WITH(UPDLOCK,HOLDLOCK) ON v.id=l.invoice_id CROSS APPLY OPENJSON(l.preview_json) WITH(nativeCreationProofJSON nvarchar(max) '$.nativeCreationProofJSON') snapshot WHERE v.id=@invoice AND j.actor_id=17 AND j.operation=N'sale_draft' AND j.payload_hash=CONVERT(varchar(64),HASHBYTES('SHA2_256',j.payload_json),2) AND JSON_VALUE(j.payload_json,'$.canonicalBusinessSaleProfileHash')=${lit(profileHash)} AND JSON_VALUE(j.payload_json,'$.operationOrigin')=N'CANONICAL_TEST_BUSINESS_SALE' AND JSON_VALUE(j.payload_json,'$.testProfile')=N'B6-CANONICAL-BUSINESS-SALE-V1' AND v.customer_id=TRY_CONVERT(bigint,JSON_VALUE(j.payload_json,'$.customerId')) AND v.party_currency_account_id=TRY_CONVERT(bigint,JSON_VALUE(j.payload_json,'$.customerAccountId')) AND v.document_currency=JSON_VALUE(j.payload_json,'$.currency') AND ((@operation=N'sale_finalize' AND v.status=N'draft') OR(@operation=N'sale_cancel' AND v.status IN(N'draft',N'finalized')));
IF @creation IS NULL ${fail('CREATION_JOURNAL')}
SELECT @selection=(SELECT JSON_VALUE(@creation,'$.customerId') customerId,JSON_VALUE(@creation,'$.customerAccountId') customerAccountId,JSON_VALUE(@creation,'$.documentDate') documentDate,JSON_VALUE(@creation,'$.currency') currency,JSON_QUERY(@creation,'$.items') items FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); END;
IF @operation<>N'sale_cancel' BEGIN ${resolvePin} EXEC ${O.resolve} @actor_id=@actor_id,@selection_json=@selection,@proof_json=@proof OUTPUT,@context_json=@context OUTPUT,@operation=@operation; END;
ELSE BEGIN
IF ISNULL(ISJSON(@creationNative),0)<>1 OR ISNULL(JSON_VALUE(@creationNative,'$.profileHash'),'')<>${lit(profileHash)} OR ISNULL(JSON_VALUE(@creationNative,'$.operation'),'')<>N'sale_draft' OR ISNULL(JSON_VALUE(@creationNative,'$.actorId'),'')<>N'17' OR ISNULL(JSON_VALUE(@creationNative,'$.requestId'),'')<>LOWER(CONVERT(varchar(36),@creationRequest)) OR ISNULL(JSON_VALUE(@creationNative,'$.bodyHash'),'')<>CONVERT(varchar(64),HASHBYTES('SHA2_256',@creation),2) ${fail('CREATION_OWNER_PROOF')}
IF (SELECT COUNT(*) FROM OPENJSON(@creationNative,'$.products')) NOT BETWEEN 1 AND 2 OR (SELECT COUNT(*) FROM dbo.sales_invoice_items WHERE sales_invoice_id=@invoice)<>(SELECT COUNT(*) FROM OPENJSON(@creationNative,'$.products')) ${fail('CREATION_ITEMS')}
IF NOT EXISTS(SELECT 1 FROM dbo.sales_invoices v WITH(UPDLOCK,HOLDLOCK) JOIN dbo.party_currency_accounts a WITH(UPDLOCK,HOLDLOCK) ON a.id=v.party_currency_account_id JOIN dbo.customers c WITH(UPDLOCK,HOLDLOCK) ON c.id=v.customer_id AND c.party_entity_id=a.party_entity_id WHERE v.id=@invoice AND v.customer_id=TRY_CONVERT(bigint,JSON_VALUE(@creationNative,'$.customerId')) AND v.party_entity_id=TRY_CONVERT(bigint,JSON_VALUE(@creationNative,'$.partyEntityId')) AND a.id=TRY_CONVERT(bigint,JSON_VALUE(@creationNative,'$.accountId')) AND a.customer_id=c.id AND a.supplier_id IS NULL AND a.party_entity_id=v.party_entity_id AND a.currency_code=v.document_currency AND a.currency_code=JSON_VALUE(@creationNative,'$.currency') AND CONVERT(varbinary(max),a.source_record_key)=CONVERT(varbinary(max),JSON_VALUE(@creationNative,'$.accountSourceKey')) AND a.current_balance IS NOT NULL AND c.is_active=1 AND c.is_deleted=0 AND v.account_currency=v.document_currency AND v.account_amount=v.grand_total AND v.grand_total=TRY_CONVERT(decimal(18,4),JSON_VALUE(@creationNative,'$.grandTotalExact4')) AND v.amount_try=TRY_CONVERT(decimal(18,4),JSON_VALUE(@creationNative,'$.amountTryExact4')) AND v.exchange_rate_snapshot=TRY_CONVERT(decimal(18,8),JSON_VALUE(@creationNative,'$.rateExact8')) AND v.account_exchange_rate_snapshot=v.exchange_rate_snapshot) ${fail('CREATION_ACCOUNT_SNAPSHOT')}
IF EXISTS(SELECT 1 FROM OPENJSON(@creationNative,'$.products') WITH(productId bigint '$.productId',quoteId bigint '$.quoteId',sourceKey nvarchar(max) '$.sourceKey',unitSourceId int '$.unitSourceId',quantity decimal(18,3) '$.quantityExact3',price4 decimal(18,4) '$.unitPriceExact4',line4 decimal(18,4) '$.lineTotalExact4',cost4 decimal(18,4) '$.averageCostTryExact4',stockCode nvarchar(max) '$.stockCode',name nvarchar(max) '$.name') x WHERE NOT EXISTS(SELECT 1 FROM dbo.products p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.product_prices q WITH(HOLDLOCK) ON q.id=x.quoteId AND q.product_id=p.id JOIN dbo.sales_invoice_items i WITH(UPDLOCK,HOLDLOCK) ON i.sales_invoice_id=@invoice AND i.product_id=p.id WHERE p.id=x.productId AND CONVERT(varbinary(max),p.source_record_key)=CONVERT(varbinary(max),x.sourceKey) AND p.is_active=1 AND p.is_deleted=0 AND p.unit COLLATE Latin1_General_100_BIN2=N'ADET' AND p.current_stock_qty IS NOT NULL AND q.source_unit_id=x.unitSourceId AND q.currency_code=JSON_VALUE(@creationNative,'$.currency') AND q.price_type COLLATE Latin1_General_100_BIN2=N'sale' AND i.quantity=x.quantity AND i.unit_price=x.price4 AND i.line_total=x.line4 AND i.average_cost_try_snapshot=x.cost4 AND CONVERT(varbinary(max),i.stock_code_snapshot)=CONVERT(varbinary(max),x.stockCode) AND CONVERT(varbinary(max),i.product_name_snapshot)=CONVERT(varbinary(max),x.name))) ${fail('CREATION_PRODUCT_SNAPSHOT')}
IF EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds h WHERE (h.entity=N'customer' AND h.native_id=TRY_CONVERT(bigint,JSON_VALUE(@creationNative,'$.customerId'))) OR(h.entity=N'product' AND EXISTS(SELECT 1 FROM OPENJSON(@creationNative,'$.products') WITH(productId bigint '$.productId') p WHERE p.productId=h.native_id))) ${fail('HOLD')}
SET @proof=JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(@creationNative,'$.sessionId',@@SPID),'$.transactionId',CONVERT(varchar(20),CURRENT_TRANSACTION_ID())),'$.context',NULL);
END;
IF @operation=N'sale_draft' BEGIN IF ISNULL(JSON_VALUE(@payload_json,'$.expectedRevision'),'') COLLATE Latin1_General_100_BIN2<>JSON_VALUE(@proof,'$.revision') COLLATE Latin1_General_100_BIN2 OR ISNULL(JSON_VALUE(@payload_json,'$.previewHash'),'') COLLATE Latin1_General_100_BIN2<>JSON_VALUE(@proof,'$.previewHash') COLLATE Latin1_General_100_BIN2 ${fail('STALE_PREVIEW')} SET @proof=JSON_MODIFY(@proof,'$.context',JSON_QUERY(@context)); END;
ELSE BEGIN SELECT @revision=${canonicalBusinessSaleInvoiceRevisionSQL({profileHash})} FROM dbo.sales_invoices v WITH(UPDLOCK,HOLDLOCK) WHERE v.id=@invoice;
IF ISNULL(JSON_VALUE(@payload_json,'$.expectedRevision'),'') COLLATE Latin1_General_100_BIN2<>@revision COLLATE Latin1_General_100_BIN2 ${fail('STALE_INVOICE')}
SET @proof=JSON_MODIFY(@proof,'$.revision',@revision); END;
SET @proof=JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(JSON_MODIFY(@proof,'$.requestId',LOWER(CONVERT(varchar(36),@request_id))),'$.operation',@operation),'$.bodyHash',@bodyHash),'$.write',CAST(1 AS bit));IF @invoice IS NOT NULL SET @proof=JSON_MODIFY(@proof,'$.invoiceId',CONVERT(varchar(20),@invoice));
${beforeJSON}
INSERT ${O.intents}(session_id,transaction_id,request_id,actor_id,operation,body_hash,payload_json,proof_json,before_json,invoice_id,phase,phase_json) VALUES(@@SPID,CURRENT_TRANSACTION_ID(),@request_id,@actor_id,@operation,@bodyHash,@payload_json,@proof,@before,@invoice,N'ISSUED',N'{}');
SELECT @proof proof_json,CAST(0 AS bit) replayed;`);
 const assertDefinition=proc(O.assert,'@request_id uniqueidentifier,@actor_id bigint,@operation nvarchar(40),@completed bit=0',`${readyCall}
IF @completed IS NULL ${fail('COMPLETED_ARGUMENT')}
IF APPLOCK_MODE(N'public',N'melisa-canonical-business-sale:${profileHash}',N'Transaction')<>N'Exclusive' ${fail('EXCLUSIVE_LOCK')}
DECLARE @proof nvarchar(max),@body nvarchar(max),@bodyHash char(64),@invoice bigint,@phase nvarchar(20);
IF (SELECT COUNT(*) FROM ${O.intents} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID() AND request_id=@request_id AND actor_id=@actor_id AND operation=@operation)<>1 ${fail('INTENT_AUTHORITY')}
SELECT @proof=proof_json,@body=payload_json,@bodyHash=body_hash,@invoice=invoice_id,@phase=phase FROM ${O.intents} WITH(UPDLOCK,HOLDLOCK) WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID() AND request_id=@request_id AND actor_id=@actor_id AND operation=@operation;
IF @completed=1 BEGIN
IF @phase<>N'DONE' OR @bodyHash<>CONVERT(varchar(64),HASHBYTES('SHA2_256',@body),2) OR NOT EXISTS(SELECT 1 FROM dbo.work_trade_requests j WITH(UPDLOCK,HOLDLOCK) WHERE j.request_id=@request_id AND j.actor_id=@actor_id AND j.operation=@operation AND j.payload_hash=@bodyHash AND CONVERT(varbinary(max),j.payload_json)=CONVERT(varbinary(max),@body)) ${fail('COMPLETED_JOURNAL')}
SELECT CAST(1 AS bit) completed,LOWER(CONVERT(varchar(36),@request_id)) requestId,CONVERT(varchar(20),@actor_id) actorId,@operation operation,@bodyHash bodyHash,CONVERT(varchar(64),HASHBYTES('SHA2_256',j.response_json),2) responseHash,N'DONE' phase FROM dbo.work_trade_requests j WHERE j.request_id=@request_id; RETURN; END;
IF @phase NOT IN(${CANONICAL_BUSINESS_SALE_PHASES.filter(p=>!['EFFECTS_VERIFIED','JOURNALED','DONE'].includes(p)).map(lit).join(',')}) OR @bodyHash<>CONVERT(varchar(64),HASHBYTES('SHA2_256',@body),2) OR ISNULL(JSON_VALUE(@proof,'$.profileHash'),'')<>${lit(profileHash)} OR ISNULL(JSON_VALUE(@proof,'$.actorId'),'')<>N'17' OR ISNULL(TRY_CONVERT(int,JSON_VALUE(@proof,'$.sessionId')),-1)<>@@SPID OR ISNULL(TRY_CONVERT(bigint,JSON_VALUE(@proof,'$.transactionId')),-1)<>CURRENT_TRANSACTION_ID() OR ISNULL(JSON_VALUE(@proof,'$.requestId'),'')<>LOWER(CONVERT(varchar(36),@request_id)) OR ISNULL(JSON_VALUE(@proof,'$.operation'),'') COLLATE Latin1_General_100_BIN2<>@operation OR ISNULL(JSON_VALUE(@proof,'$.bodyHash'),'')<>@bodyHash OR (@operation<>N'sale_draft' AND ISNULL(JSON_VALUE(@proof,'$.invoiceId'),'')<>ISNULL(CONVERT(varchar(20),@invoice),'')) OR (@operation=N'sale_draft' AND JSON_VALUE(@proof,'$.invoiceId') IS NOT NULL) OR (@operation=N'sale_draft' AND @phase<>N'ISSUED' AND @invoice IS NULL) ${fail('INTENT_PROOF')}
SELECT @proof proof_json;`);
 const modules=Object.freeze([{name:O.ready,definition:readyDefinition},{name:O.resolve,definition:resolve},{name:O.context,definition:contextDefinition},{name:O.begin,definition:beginDefinition},{name:O.assert,definition:assertDefinition},...immutable].map(m=>Object.freeze({...m,definitionHash:sha(m.definition)})));
