 const permissionSQL=Object.freeze([...publicModules.map(n=>`GRANT EXECUTE ON OBJECT::${n} TO [${O.login}];`),...viewModules.map(n=>`GRANT VIEW DEFINITION ON OBJECT::${n} TO [${O.login}];`),...privateTables.map(n=>`DENY SELECT,INSERT,UPDATE,DELETE ON OBJECT::${n} TO [${O.login}];`)]);
 return Object.freeze({schemaVersion:'melisa-canonical-business-sale-owner-sql.v1',status:'COHERENT_MIGRATION_REQUIRED',installable:false,profileHash,sourceEvidence:'OWNER_CAPTURE_INPUT_REQUIRES_EXTERNAL_APPROVAL',businessWrites:0,legacyManifestWrites:0,journalReplacement:0,grants:4+viewModules.length,executeGrants:4,viewDefinitionGrants:viewModules.length,broadPermissionGrants:0,nativePermissionChanges:0,permissionsApplied:0,tables:Object.freeze(tables),indexes,seedSQL,permissionSQL,modules,contract:O,intentColumns:CANONICAL_BUSINESS_SALE_INTENT_COLUMNS,intentPhases:CANONICAL_BUSINESS_SALE_PHASES,requiresEffectsCompiler:true,requiresImmutableSuccessorProjection:true});
